import json
import os
from typing import Any, Dict, Optional

DEFAULT_CONFIG = {
    "debug": False,
    "host": "localhost",
    "port": 8000,
    "timeout": 30,
    "max_retries": 3,
    "log_level": "INFO",
}


class Config:
    """Load and manage application configuration from JSON files."""

    def __init__(self, config_path: Optional[str] = None) -> None:
        self.config_path = config_path or os.getenv("CONFIG_PATH", "config.json")
        self.data = self._load_config()

    def _load_config(self) -> Dict[str, Any]:
        """Load configuration from file, falling back to defaults if missing."""
        config = DEFAULT_CONFIG.copy()

        try:
            if os.path.exists(self.config_path):
                with open(self.config_path, "r") as f:
                    file_config = json.load(f)
                    config.update(file_config)
        except (json.JSONDecodeError, IOError) as e:
            print(f"Warning: Could not load config from {self.config_path}: {e}")

        return config

    def get(self, key: str, default: Any = None) -> Any:
        """Get a configuration value by key with optional default."""
        return self.data.get(key, default)

    def __getitem__(self, key: str) -> Any:
        """Enable dictionary-style access to configuration values."""
        return self.data[key]

    def __contains__(self, key: str) -> bool:
        """Check if a configuration key exists."""
        return key in self.data
